"""M1-T17 intent: rolling volatility uses only earlier returns (RISK-02, TC-05)."""

from __future__ import annotations

import pytest

from risk import Returns, rolling_vol


def as_returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


@pytest.mark.intent
def test_tc05_rolling_vol_is_sample_stdev_of_earlier_returns(golden):
    given, expected = golden("risk", "TC-05")
    returns = as_returns(given["returns"])

    vol = rolling_vol(returns, given["window"])

    assert vol.returns == returns
    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(returns.dates)
        assert [v is None for v in got] == [w is None for w in want]
        assert [v for v in got if v is not None] == pytest.approx(
            [w for w in want if w is not None], abs=expected["tol"], rel=0
        )


@pytest.mark.intent
@pytest.mark.parametrize("window", [1, 0, -1])
def test_window_below_two_is_a_value_error(contract_sample, window):
    returns = as_returns(contract_sample("risk.Returns"))

    with pytest.raises(ValueError, match="at least 2"):
        rolling_vol(returns, window)

